SELECT CASE WHEN account_type IN ('LOAN', 'CREDIT') THEN 'core' ELSE 'other' END AS account_type_group, MAX(balance) - MIN(balance) AS balance_range, SUM(CASE WHEN account_type = 'CREDIT' THEN balance ELSE 0 END) AS credit_balance FROM accounts WHERE customer_id IS NOT NULL AND account_type = 'LOAN' GROUP BY CASE WHEN account_type IN ('LOAN', 'CREDIT') THEN 'core' ELSE 'other' END HAVING SUM(CASE WHEN account_type = 'CREDIT' THEN balance ELSE 0 END) >= 37 ORDER BY credit_balance DESC;
